(27861, 'Revelation 13:11', 'Revelation', 13, 11, 'بیا ما یو بل ځناور ولیده چې د ځمکې نه راووت. هغه د وري په شان دوه ښکرونه لرل او د ښامار په شان یې خبرې کولې.', 'بیا ما یو بل جناور ولیده چې د جمکې نه راووت. هغه د وری په شان دوه شکرونه لرل او د شامار په شان یې خبرې کولې.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Revelation_13_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27862, 'Revelation 13:12', 'Revelation', 13, 12, 'هغه د لومړني ځناور په شتون کې د هغه د ټول واک او اختیار څخه کار اخیسته او ټوله ځمکه او د هغې اوسېدونکي یې دې ته مجبورول چې د هغه لومړني حیوان عبادت وکړي چې وژونکی زخم یې جوړ شوی ؤ.', 'هغه د لومرنی جناور په شتون کې د هغه د تول واک او اختیار چخه کار اخیسته او توله جمکه او د هغې اوسېدونکی یې دې ته مجبورول چې د هغه لومرنی حیوان عبادت وکری چې وژونکی زخم یې جور شوی و.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Revelation_13_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27863, 'Revelation 13:13', 'Revelation', 13, 13, 'هغه لویې معجزې ښودلې، تر دې پورې چې د خلکو په مخکې یې د اسمان نه په ځمکه باندې اور ووراوه.', 'هغه لویې معجزې شودلې، تر دې پورې چې د خلکو په مخکې یې د اسمان نه په جمکه باندې اور ووراوه.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Revelation_13_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27864, 'Revelation 13:14', 'Revelation', 13, 14, 'هغه په هغو معجزو سره چې اجازه ورکړل شوې وه چې د لومړني ځناور په حضور کې یې وښایي، د ځمکې اوسېدونکي غولول. هغوی ته یې ویل چې د هغه لومړني ځناور مجسمه جوړه کړي چې په توره باندې زخمي شوی ؤ او تر‌اوسه لا ژوندی دی.', 'هغه په هغو معجزو سره چې اجازه ورکرل شوې وه چې د لومرنی جناور په حضور کې یې وشایی، د جمکې اوسېدونکی غولول. هغوی ته یې ویل چې د هغه لومرنی جناور مجسمه جوره کری چې په توره باندې زخمی شوی و او تر‌اوسه لا ژوندی دی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Revelation_13_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27865, 'Revelation 13:15', 'Revelation', 13, 15, 'هغه ته اجازه ورکړل شوه چې د لومړني ځناور په مجسمه کې ساه واچوي چې خبرې وکړي او وکولای شي هغه خلک ووژني چې د هغې مجسمې عبادت نه کوي.', 'هغه ته اجازه ورکرل شوه چې د لومرنی جناور په مجسمه کې ساه واچوی چې خبرې وکری او وکولای شی هغه خلک ووژنی چې د هغې مجسمې عبادت نه کوی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Revelation_13_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27866, 'Revelation 13:16', 'Revelation', 13, 16, 'هغه ټول خلک د کوچنیو نه نیولې تر لویانو، شتمنو نه تر غریبو، ازادو نه تر غلامانو پورې مجبورول چې په خپل ښي لاس یا تندي باندې یوه نښه ولګوي.', 'هغه تول خلک د کوچنیو نه نیولې تر لویانو، شتمنو نه تر غریبو، ازادو نه تر غلامانو پورې مجبورول چې په خپل شی لاس یا تندی باندې یوه نشه ولګوی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Revelation_13_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27867, 'Revelation 13:17', 'Revelation', 13, 17, 'هېچا نه شو کولای چې څه شی واخلي او یا یې خرڅ کړي، ترڅو پورې چې هغه نښه یا د هغه ځناور د نوم شمېره پرې نه وي لګېدلې چې د هغه د نوم څرګندونه کوي.', 'هېچا نه شو کولای چې چه شی واخلی او یا یې خرچ کری، ترچو پورې چې هغه نشه یا د هغه جناور د نوم شمېره پرې نه وی لګېدلې چې د هغه د نوم چرګندونه کوی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Revelation_13_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(27868, 'Revelation 13:18', 'Revelation', 13, 18, 'د دې دپاره پوهه او حکمت په کار دی. نو څوک چې پوه وي باید د هغه ځناور د شمېرې په معنی پوه شي، ځکه چې دا د انسان شمېره ده. هغه شمېره ده ۶۶۶.', 'د دې دپاره پوهه او حکمت په کار دی. نو چوک چې پوه وی باید د هغه جناور د شمېرې په معنی پوه شی، جکه چې دا د انسان شمېره ده. هغه شمېره ده ۶۶۶.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Revelation_13_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
